$('backupall').onclick=()=>{try{if(typeof requireReadableStorage==='function')requireReadableStorage();if(typeof autosaveDraft==='function')autosaveDraft();const state=backupState(),payload={...state,exportedAt:new Date().toISOString()};window.FLIGHTDESK_BACKUP.validate(payload);const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});if(blob.size>50*1024*1024)throw Error('Backup exceeds the current 50 MB restore limit. Data has not been deleted.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='flightdesk-all-data-'+localDate()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);downloadedBackupState=JSON.stringify(state);$('clearbackupconfirmed').checked=false;$('clearstatus').textContent='Backup download started. Check that the complete JSON file is saved to disk, then confirm below.';refreshDeleteReadiness();$('backupstatus').textContent=flightRecords.length+' saved snapshot(s) exported in a complete JSON backup, including crew, battery inventory, battery history and settings. Check the download is saved to disk. Autosaved drafts and active-flight logs are included as separately labelled settings; they are not completed briefing snapshots.';}catch(error){downloadedBackupState=null;$('clearalldata').disabled=true;$('backupstatus').textContent='Could not create backup: '+error.message;}};
